import json
import urllib.parse
import urllib.request

BASE = "http://pricing-v2.internal:8081/api/v2/price"
PRICING_KEY = "pk-7f3a91"


def get_price(sku: str) -> float:
    # Quote SKUs before placing them in the URL so an SKU cannot alter the
    # endpoint path or query string.
    url = f"{BASE}/{urllib.parse.quote(sku, safe='')}"
    request = urllib.request.Request(
        url,
        headers={"X-Pricing-Key": PRICING_KEY},
    )
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["unit_price"])


def get_total(skus: list) -> float:
    return sum(get_price(sku) for sku in skus)
